NEW = [
[ [("Thành phần","Component","组成部分"),("Vai trò","Role","作用")],
  ["MAM Server",("Máy chủ trung tâm, chạy một lần trên một máy cố định. Lưu dữ liệu, phục vụ Console, giao tiếp với agent.","Central server, runs once on one always-on machine. Stores data, serves the Console, talks to agents.","中心服务器，在一台常开的机器上运行一次。保存数据、提供控制台、与代理通信。")],
  ["MAM Console",("Trang web quản trị, mở bằng trình duyệt tại địa chỉ của server.","The admin web page, opened in a browser at the server address.","管理网页，用浏览器访问服务器地址。")],
  ["MAM Agent",("Chương trình nhỏ chạy ngầm trên mỗi máy cần giám sát. Gửi số liệu về server khoảng 5 giây một lần và nhận lệnh.","A small background program on every monitored machine. Sends metrics to the server about every 5 seconds and receives commands.","在每台被监控设备上后台运行的小程序。约每 5 秒向服务器上报数据并接收命令。")]],
[ [("Lệnh","Command","命令"),("Cách thực hiện","How it works","实现方式")],
  [("Khóa màn hình","Lock screen","锁定屏幕"),("Ngắt phiên đang ngồi (tsdiscon), về màn hình đăng nhập. Cần Windows Pro trở lên.","Disconnects the active session (tsdiscon) back to the sign-in screen. Needs Windows Pro or later.","断开当前会话 (tsdiscon)，回到登录界面。需要 Windows 专业版及以上。")],
  [("Gửi tin nhắn","Send message","发送消息"),("Hộp thoại hiện 2 phút trên màn hình (msg.exe), tối đa 300 ký tự. Cần Windows Pro trở lên.","A dialog shown for 2 minutes (msg.exe), at most 300 characters. Needs Windows Pro or later.","屏幕上显示 2 分钟的对话框 (msg.exe)，最多 300 个字符。需要 Windows 专业版及以上。")],
  [("Khởi động lại, Tắt máy","Restart, Shut down","重启、关机"),("shutdown /t 10: người dùng có 10 giây. Ghi nhật ký loại Nhạy cảm.","shutdown /t 10: the user gets 10 seconds. Logged as Sensitive.","shutdown /t 10：用户有 10 秒时间。记为“敏感”日志。")],
  [("Bật máy (Wake-on-LAN)","Wake up (Wake-on-LAN)","开机 (Wake-on-LAN)"),("Server gửi gói UDP đánh thức tới MAC của máy. Máy phải bật WoL trong BIOS và card mạng, cùng mạng LAN.","The server sends a UDP magic packet to the machine's MAC. WoL must be enabled in BIOS and NIC, on the same LAN.","服务器向设备的 MAC 发送 UDP 魔术包。需在 BIOS 和网卡中启用 WoL，且在同一局域网。")]],
[ [("Điều kiện","Condition","条件"),("Mặc định","Default","默认")],
  [("Nhiệt độ CPU","CPU temperature","CPU 温度"),"≥ 85 °C"],
  [("CPU cao liên tục","Sustained CPU","CPU 持续高负载"),"≥ 90 % (~30 s)"],
  [("Ổ cứng còn trống","Free disk space","磁盘剩余空间"),"≤ 10 %"],
  [("Mất kết nối","Lost connection","断线"),("5 phút","5 min","5 分钟")]],
[ [("Vai trò","Role","角色"),("Quyền","Permissions","权限")],
  ["Super admin",("Toàn quyền, gồm tài khoản, nhóm, cài đặt, thu hồi máy.","Full control, including accounts, groups, settings and revoking machines.","全部权限，包括账号、分组、设置、吊销设备。")],
  [("Kỹ thuật viên","Technician","技术员"),("Xem máy, xử lý cảnh báo, ra lệnh, chỉ cho máy trong nhóm được giao. Lệnh nguy hiểm vẫn được nhưng ghi nhật ký Nhạy cảm. Không quản lý tài khoản, nhóm, cài đặt; chỉ xem nhật ký của chính mình.","View machines, handle alerts, send commands, only for machines in assigned groups. Dangerous commands are allowed but logged as Sensitive. Cannot manage accounts, groups or settings; sees only their own audit log.","查看设备、处理告警、下发命令，仅限所分配分组内的设备。危险命令允许但记为“敏感”日志。不能管理账号、分组、设置；只能查看自己的日志。")],
  [("Chỉ xem","View only","只读"),("Chỉ theo dõi, không ra lệnh.","Monitoring only, no commands.","仅监控，不能下发命令。")]],
[ [("Hiện tượng","Symptom","现象"),("Cách xử lý","What to do","处理方法")],
  [("Máy không hiện trong Console","A machine does not appear in the Console","设备未出现在控制台"),("Mở http://địa-chỉ-server:7070 trên chính máy client; không vào được thì kiểm tra tường lửa và địa chỉ. Xem agent.log trong C:\\Program Files\\MAM Agent. Server có mã đăng ký thì phải cài kèm -key.","Open http://server-address:7070 on the client itself; if that fails check the firewall and the address. Read agent.log in C:\\Program Files\\MAM Agent. If the server has an enrollment key, install with -key.","在客户端本机打开 http://服务器地址:7070；打不开则检查防火墙和地址。查看 C:\\Program Files\\MAM Agent 中的 agent.log。服务器设置了注册码时，安装需加 -key。")],
  [("Máy hiện Offline dù đang bật","Shows Offline while powered on","设备开机却显示离线"),("Agent bị tắt hoặc mất mạng. Server đổi địa chỉ thì cài lại agent. Máy đã bị thu hồi cũng ngủ 5 phút rồi thử lại.","The agent stopped or the network is down. If the server address changed, reinstall the agent. A revoked machine also sleeps 5 minutes and retries.","代理已停止或网络中断。服务器地址变更时请重新安装代理。被吊销的设备会休眠 5 分钟后重试。")],
  [("Khóa màn hình hoặc nhắn tin báo lỗi","Lock or message fails","锁屏或消息失败"),("Cần Windows Pro trở lên (bản Home không có tsdiscon và msg).","Needs Windows Pro or later (Home has no tsdiscon or msg).","需要 Windows 专业版及以上（家庭版没有 tsdiscon 和 msg）。")],
  [("Bật máy (WoL) không dậy","Wake-on-LAN does nothing","唤醒无效"),("Bật Wake-on-LAN trong BIOS và trong thuộc tính card mạng, tắt Fast Startup, máy phải cùng mạng LAN với server.","Enable Wake-on-LAN in the BIOS and in the NIC properties, disable Fast Startup, and keep the machine on the server's LAN.","在 BIOS 和网卡属性中启用 Wake-on-LAN，关闭快速启动，设备需与服务器在同一局域网。")],
  [("Không vào được Console","The Console does not open","无法打开控制台"),("Kiểm tra tác vụ MAM Server đang chạy, cổng không bị chương trình khác dùng, tường lửa cho phép cổng. Xem server.log trong thư mục dữ liệu.","Check that the MAM Server task is running, the port is not used by another program, and the firewall allows it. Read server.log in the data folder.","检查 MAM Server 任务是否运行、端口是否被其他程序占用、防火墙是否放行。查看数据文件夹中的 server.log。")]],
]
